sketches.source:
setcpm(90/4)

// One interface sound per bar, five bars in a loop
// Bar 1: two soft clicks, short and high
click: s("<[click ~ click ~] ~ ~ ~ ~>").hpf(2500).decay(.03).sustain(0).gain(.35)

// Bar 2: a toggle, a short square blip up a fifth
toggle: note("<~ [c6 ~ g6 ~] ~ ~ ~>").s("square").pw(.3).decay(.04).sustain(0).gain(.12)

// Bar 3: a notification, two bell-like FM notes
notify: note("<~ ~ [e5 b5 ~ ~] ~ ~>").s("sine").fm(2).fmh(3.5)
  .decay(.6).sustain(0).release(.6).room(.3).gain(.2)

// Bar 4: success, a quick major arpeggio on glass
success: note("<~ ~ ~ [c5 e5 g5 c6] ~>").s("triangle").timbre("glass")
  .decay(.3).sustain(0).release(.4).gain(.2)

// Bar 5: an error, a low semitone cluster buzzing twice
error: note("<~ ~ ~ ~ [[a2,bb2] ~ [a2,bb2] ~]>").s("square").pw(.5).lpf(1200)
  .decay(.15).sustain(.3).release(.05).gain(.14)

setcpm(120/4)

// Bar 1: a coin, two square notes a fourth apart
coin: note("<[b5 e6@3] ~ ~ ~ ~ ~>").s("square").pw(.5).decay(.3).sustain(0).gain(.14)

// Bar 2: a jump; penv starts the note an octave low and slides it up into place
jump: note("<~ [c5 ~ ~ ~] ~ ~ ~ ~>").s("square").pw(.25).penv(-12).pdecay(.15)
  .decay(.2).sustain(0).gain(.14)

// Bar 3: three laser shots; penv starts two octaves high and falls fast
laser: note("<~ ~ [c6 c6 c6 ~] ~ ~ ~>").s("square").pw(.2).penv(24).pdecay(.08)
  .decay(.1).sustain(0).gain(.1)

// Bar 4: a power-up, a fast run up the scale
powerup: n("<~ ~ ~ [0 2 4 7 9 11 14 16] ~ ~>").scale("C:major").transpose(12)
  .s("square").pw(.3).decay(.06).sustain(0).gain(.12)

// Bar 5: an explosion, noise crushed to four bits, over a falling sub thump
boom: s("<~ ~ ~ ~ [white ~ ~ ~] ~>").crush(4).lpf(1500).decay(.8).sustain(0).release(.4).gain(.4)
thump: note("<~ ~ ~ ~ [c1 ~ ~ ~] ~>").s("sine").penv(24).pdecay(.2).decay(.8).sustain(0).gain(.5)

// Bar 6: game over, a sad chromatic slide down
gameover: note("<~ ~ ~ ~ ~ [g4 f#4 f4 e4@4]>").s("square").pw(.5)
  .decay(.2).sustain(.5).release(.1).gain(.12)

setcpm(60/4)

// Wind outside the old house, and a clock ticking on the right
wind: s("wind").slow(8).intensity(.4).gain(.12)
clock: s("tick ~ tick ~").azimuth(80).distance(4).gain(.05)

// A door creaks open slowly on your left: the creak played at a lower speed, in a stone space
door: s("<[creak ~ ~ ~] ~ ~ ~>").speed(.6).azimuth(-60).distance(3).space("church").gain(.3)

// Footsteps in the room above, muffled by the floorboards
upstairs: s("<~ [step ~ step ~] [step ~ step ~] ~>").elevation(60).distance(4).occlude(.5).gain(.2)

// Thunder on the fourth bar
thunder: s("<~ ~ ~ [lt ~ ~ ~]>").speed(.4).lpf(300).room(.9).size(.95).gain(.5)

// Your heartbeat, in the middle of your head
heart: s("bd ~ bd ~ ~ ~ ~ ~").lpf(150).gain(.35)

// Whispers circling your head once every four bars
whispers: s("whisper*2?0.5").syl("<sha ho>").azimuth(saw.range(-180, 180).slow(4))
  .distance(1.5).posglide(.3).seed("ghost").gain(.08)

setcpm(90/4)

// Bar 1: a slide whistle, a hollow sine gliding up an octave and back down
slide: note("<[c5 c6 c5@2] ~ ~ ~ ~>").s("sine").timbre("hollow").mono(1).glide(.35)
  .attack(.02).sustain(1).release(.1).gain(.2)

// Bar 2: a boing, a fast, deep vibrato on a note that springs up from below
boing: note("<~ c3 ~ ~ ~>").s("sine").vib(14).vibdepth(4).penv(-12).pdecay(.3)
  .decay(.8).sustain(0).gain(.3)

// Bar 3: a bonk on the head, then little birdies
bonk: s("<~ ~ [lt ~ ~ ~] ~ ~>").speed(2.5).lpf(3000).gain(.5)
birdies: note("<~ ~ [~ [c7 e7] [g7 e7] c7] ~ ~>").s("sine").decay(.1).sustain(0).gain(.06)

// Bar 4: four zips, a pulse sweeping up fast
zip: freq(saw.range(300, 3000).fast(4).segment(32)).s("square").pw(.3).mono(1).glide(.01)
  .mask("<0 0 0 1 0>").sustain(1).release(.02).gain(.06)

// Bar 5: a clown horn, a reedy saw through an a vowel
honk: note("<~ ~ ~ ~ [f3 ~ f3@2]>").s("sawtooth").timbre("reed").vowel("a").lpf(1800)
  .attack(.01).sustain(.8).release(.05).gain(.2)

setcpm(60/4)

// Rain that swells and eases over four bars, and the wind behind it
rain: s("rain").intensity("<.2 .4 .7 .4>").gain(.3)
wind: s("wind").slow(8).intensity(.4).gain(.12)

// The lightning crack: a short burst of crushed white noise, high and dry
crack: s("<~ ~ [white ~ ~ ~] ~>").hpf(2000).crush(6).decay(.15).sustain(0).gain(.3)

// The thunder rolls in just after: brown noise, a slow decay and a big reverb
rumble: s("<~ ~ [~ brown] ~>").lpf(300).attack(.05).decay(3).sustain(0).release(2)
  .room(.8).size(.95).gain(.4)

// Drips from the gutter, each in a new place around you
drips: s("drip*8?0.4").azimuth(rand.range(-150, 150)).distance(2).seed("gutter").gain(.1)

setcpm(90/4)

// Your keyboard: seeded clicks at slightly different speeds, like keys of different sizes
typing: s("click*16?0.6").hpf(2500).speed(rand.range(.8, 1.3))
  .azimuth(-20).distance(1).seed("typing").gain(.15)
mouse: s("<[~ ~ ~ click] ~ [~ click ~ ~] ~>").speed(.7).azimuth(30).distance(.8).gain(.2)

// A phone ringing across the room: two notes trembling twenty times a second
phone: note("<~ [[e5,g5] ~ [e5,g5] ~] ~ ~>").s("sine").trem(20).tremdepth(1)
  .sustain(1).release(.05).azimuth(100).distance(4).gain(.06)

// The printer behind you on the left
printer: s("<~ ~ engine*8 ~>").hpf(400).lpf(2000).azimuth(-120).distance(5).gain(.1)

// The elevator arrives
ding: note("<~ ~ ~ [~ ~ e5 c5]>").s("sine").fm(2).fmh(3.5).decay(1).sustain(0)
  .azimuth(160).distance(6).gain(.1)

// Air conditioning and chatter from the next room
aircon: s("pink").slow(8).lpf(800).icorr(.3).gain(.03)
chatter: s("crowd").slow(8).intensity(.2).occlude(.5).gain(.06)

setcpm(110/4)

// One path for everything: a full circle around your head every eight bars
const path = saw.range(-180, 180).slow(8)

// Bars 1-2 wood, 3-4 gravel, 5-6 puddles, 7-8 up the stairs
// The surfaces change the speed and brightness of the step, and the stairs climb
steps: s("step*4").speed("<1 1 1.2 1.2 .9 .9 1 1>").lpf("<2000 2000 5000 5000 3000 3000 2500 2500>")
  .azimuth(path).elevation("<0 0 0 0 0 0 10 30>").distance(2).posglide(.3).gain(.3)

// Gravel: a crunch of filtered noise on each step
gravel: s("pink*4").hpf(2500).decay(.08).sustain(0).mask("<0 0 1 1 0 0 0 0>")
  .azimuth(path).distance(2).posglide(.3).gain(.05)

// Puddles: a low splash on each step
splash: s("drip*4").speed(.6).mask("<0 0 0 0 1 1 0 0>")
  .azimuth(path).distance(2).posglide(.3).gain(.2)

// The room itself, wide and quiet
room: s("brown").slow(8).lpf(400).icorr(.3).gain(.04)

setcpm(80/4)

// Three bars of rise, one bar of impact
// The riser: pink noise whose filter and level climb across the build
riser: s("pink").mask("<1 1 1 0>").hpf(saw.range(200, 8000).slow(4)).gain(saw.range(.02, .12).slow(4))

// A clock ticking faster and faster, then silent for the hit
ticks: s("<tick*4 tick*8 tick*16 ~>").hpf(2000).gain(.12)

// A whoosh into the downbeat: a slow attack on bright noise, cut off sharply
whoosh: s("<~ ~ [~ ~ ~ white] ~>").hpf(1000).attack(.25).sustain(1).release(.02).gain(.08)

// The impact: a slowed kick and crash, driven hard into a big hall
impact: s("<~ ~ ~ [bd,cr]>").speed(.4).lpf(800).shape(.4).room(.8).size(.95).gain(.7)

// A sub that drops two octaves into place
sub: note("<~ ~ ~ c1>").s("sine").penv(24).pdecay(.15).decay(2).sustain(0).release(1).gain(.5)

// And a brass tail ringing out
tail: note("<~ ~ ~ [c3,g3,c4]>").s("sawtooth").unison(4).detune(25).lpf(1200)
  .attack(.01).decay(3).sustain(0).release(2).space("hall").gain(.12)
